'use strict';
const db = require('../config/db');

/**
 * Notify service's public.users schema (confirmed):
 *
 *   id            BIGINT  NOT NULL GENERATED BY DEFAULT AS IDENTITY  (PK)
 *   created_at    TIMESTAMP(6) NOT NULL
 *   email         VARCHAR(255) NOT NULL UNIQUE
 *   password_hash VARCHAR(255) NOT NULL
 *   role          VARCHAR(255) NOT NULL  CHECK (role IN ('CLIENT','ADMIN'))
 *   username      VARCHAR(255) NOT NULL
 *
 * There is NO `name` column and NO `updated_at` column.
 * pg returns BIGINT columns as JavaScript strings to avoid 64-bit precision loss.
 */

async function findByEmail(email) {
  const { rows } = await db.query(
    'SELECT * FROM public.users WHERE email = $1 LIMIT 1',
    [email]
  );
  return rows[0] || null;
}

async function findById(id) {
  const { rows } = await db.query(
    'SELECT * FROM public.users WHERE id = $1 LIMIT 1',
    [id]
  );
  return rows[0] || null;
}

/**
 * Upsert a row in public.users by email.
 *
 * For OAuth-only users, password_hash is stored as an empty string because
 * Recall never handles password auth — authentication happens exclusively
 * through Google OAuth. The Notify service owns password auth for its own
 * users; OAuth users will simply have an unusable password_hash sentinel.
 *
 * Role defaults to 'CLIENT' for all Recall-originated signups.
 *
 * Uses a transactional client so callers can batch with other writes.
 */
async function upsertPublicUser(client, { email, username }) {
  const { rows } = await client.query(
    `INSERT INTO public.users (created_at, email, username, password_hash, role)
     VALUES (now(), $1, $2, '', 'CLIENT')
     ON CONFLICT (email) DO UPDATE
       SET username = COALESCE(public.users.username, EXCLUDED.username)
     RETURNING *`,
    [email, username || email.split('@')[0]]
  );
  return rows[0];
}

async function upsertUserProfile(client, { userId, googleId, avatarUrl, timezone }) {
  const { rows } = await client.query(
    `INSERT INTO recall.user_profiles
       (user_id, google_id, avatar_url, timezone, created_at, updated_at)
     VALUES ($1, $2, $3, $4, now(), now())
     ON CONFLICT (user_id) DO UPDATE
       SET google_id  = EXCLUDED.google_id,
           avatar_url = EXCLUDED.avatar_url,
           timezone   = EXCLUDED.timezone,
           updated_at = now()
     RETURNING *`,
    [userId, googleId, avatarUrl || null, timezone || 'UTC']
  );
  return rows[0];
}

async function upsertGoogleCredentials(
  client,
  { userId, refreshTokenEncrypted, accessTokenEncrypted, tokenExpiry, scopes }
) {
  const { rows } = await client.query(
    `INSERT INTO recall.google_credentials
       (id, user_id, refresh_token_encrypted, access_token_encrypted,
        token_expiry, scopes, created_at, updated_at)
     VALUES (gen_random_uuid(), $1, $2, $3, $4, $5, now(), now())
     ON CONFLICT (user_id) DO UPDATE
       SET refresh_token_encrypted = EXCLUDED.refresh_token_encrypted,
           access_token_encrypted  = COALESCE(
             EXCLUDED.access_token_encrypted,
             recall.google_credentials.access_token_encrypted
           ),
           token_expiry            = EXCLUDED.token_expiry,
           scopes                  = EXCLUDED.scopes,
           updated_at              = now()
     RETURNING *`,
    [userId, refreshTokenEncrypted, accessTokenEncrypted || null, tokenExpiry || null, scopes || null]
  );
  return rows[0];
}

async function getGoogleCredentials(userId) {
  const { rows } = await db.query(
    'SELECT * FROM recall.google_credentials WHERE user_id = $1 LIMIT 1',
    [userId]
  );
  return rows[0] || null;
}

async function getUserProfile(userId) {
  const { rows } = await db.query(
    'SELECT * FROM recall.user_profiles WHERE user_id = $1 LIMIT 1',
    [userId]
  );
  return rows[0] || null;
}

module.exports = {
  findByEmail,
  findById,
  upsertPublicUser,
  upsertUserProfile,
  upsertGoogleCredentials,
  getGoogleCredentials,
  getUserProfile,
};
